// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_run(uint96 amount) public {
        vm.deal(address(this), 1 ether);
        uint256 v = (uint256(amount) % 1000) + 1;

        uint256 before = c.depositsCount();
        (bool ok, ) = address(c).call{value: v}(hex"deadbeefdeadbeef");

        assertTrue(ok);
        assertEq(c.depositsCount(), before + 1);
    }

    receive() external payable {}
}
